import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cuda_source = r"""
#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include <cuda_runtime.h>

// Tile sizes: each block computes a BM x BN tile of C over a slice of K.
// Each thread computes a TM x TN register tile.
#define BM 64
#define BN 64
#define BK 16
#define TM 4
#define TN 4
#define NTHREADS 256

// Split-K GEMM: K is huge (524288) while M and N are small (256), so we
// partition K across blocks in the z-dimension and atomically accumulate
// partial results into C. A is read coalesced along K, B coalesced along N.
__global__ void matmul_splitk_kernel(const float* __restrict__ A,
                                     const float* __restrict__ B,
                                     float* __restrict__ C,
                                     int M, int N, int K, int chunk)
{
    __shared__ float As[BM][BK + 4];   // padded to reduce bank conflicts
    __shared__ float Bs[BK][BN + 4];

    const int blockRow = blockIdx.y * BM;
    const int blockCol = blockIdx.x * BN;
    const int tid = threadIdx.x;
    const int threadRow = (tid / (BN / TN)) * TM;
    const int threadCol = (tid % (BN / TN)) * TN;

    const int kStart = blockIdx.z * chunk;
    const int kEnd = min(kStart + chunk, K);

    float accum[TM][TN];
    #pragma unroll
    for (int i = 0; i < TM; ++i)
        #pragma unroll
        for (int j = 0; j < TN; ++j)
            accum[i][j] = 0.0f;

    for (int k = kStart; k < kEnd; k += BK)
    {
        // Load A tile (BM x BK): consecutive threads read consecutive K
        // elements -> fully coalesced global loads from row-major A.
        #pragma unroll
        for (int i = 0; i < (BM * BK) / NTHREADS; ++i)
        {
            int idx = tid + i * NTHREADS;
            int r = idx / BK;   // M dimension
            int c = idx % BK;   // K dimension
            int gm = blockRow + r;
            int gk = k + c;
            As[r][c] = (gm < M && gk < kEnd)
                     ? A[(long long)gm * K + gk] : 0.0f;
        }
        // Load B tile (BK x BN): consecutive threads read consecutive N
        // elements -> fully coalesced global loads from row-major B.
        #pragma unroll
        for (int i = 0; i < (BK * BN) / NTHREADS; ++i)
        {
            int idx = tid + i * NTHREADS;
            int r = idx / BN;   // K dimension
            int c = idx % BN;   // N dimension
            int gk = k + r;
            int gn = blockCol + c;
            Bs[r][c] = (gk < kEnd && gn < N)
                     ? B[(long long)gk * N + gn] : 0.0f;
        }
        __syncthreads();

        #pragma unroll
        for (int kk = 0; kk < BK; ++kk)
        {
            float aReg[TM];
            float bReg[TN];
            #pragma unroll
            for (int i = 0; i < TM; ++i) aReg[i] = As[threadRow + i][kk];
            #pragma unroll
            for (int j = 0; j < TN; ++j) bReg[j] = Bs[kk][threadCol + j];
            #pragma unroll
            for (int i = 0; i < TM; ++i)
                #pragma unroll
                for (int j = 0; j < TN; ++j)
                    accum[i][j] += aReg[i] * bReg[j];
        }
        __syncthreads();
    }

    // Accumulate this block's partial K-slice into the output.
    #pragma unroll
    for (int i = 0; i < TM; ++i)
    {
        int gm = blockRow + threadRow + i;
        if (gm < M)
        {
            #pragma unroll
            for (int j = 0; j < TN; ++j)
            {
                int gn = blockCol + threadCol + j;
                if (gn < N)
                    atomicAdd(&C[(long long)gm * N + gn], accum[i][j]);
            }
        }
    }
}

torch::Tensor matmul_forward(torch::Tensor A, torch::Tensor B)
{
    TORCH_CHECK(A.is_cuda() && B.is_cuda(), "Inputs must be CUDA tensors");
    TORCH_CHECK(A.scalar_type() == torch::kFloat32 &&
                B.scalar_type() == torch::kFloat32,
                "Inputs must be float32");

    auto Ac = A.contiguous();
    auto Bc = B.contiguous();

    const int M = (int)Ac.size(0);
    const int K = (int)Ac.size(1);
    const int N = (int)Bc.size(1);

    // Output must be zero-initialized because split-K blocks accumulate
    // their partial results atomically.
    auto C = torch::zeros({M, N}, Ac.options());

    // Choose a K-split so the GPU is saturated with thread blocks.
    // chunk is rounded up to a multiple of BK so each block's loop is clean.
    int splits = 64;
    int chunk = (K + splits - 1) / splits;
    chunk = ((chunk + BK - 1) / BK) * BK;
    splits = (K + chunk - 1) / chunk;

    dim3 block(NTHREADS);
    dim3 grid((N + BN - 1) / BN, (M + BM - 1) / BM, splits);

    auto stream = at::cuda::getCurrentCUDAStream();
    matmul_splitk_kernel<<<grid, block, 0, stream>>>(
        Ac.data_ptr<float>(), Bc.data_ptr<float>(), C.data_ptr<float>(),
        M, N, K, chunk);

    return C;
}
"""

cpp_source = "torch::Tensor matmul_forward(torch::Tensor A, torch::Tensor B);"

_ext = load_inline(
    name="matmul_splitk_ext",
    cpp_sources=cpp_source,
    cuda_sources=cuda_source,
    functions=["matmul_forward"],
    extra_cuda_cflags=["-O3", "--use_fast_math"],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Matrix multiplication (C = A * B) implemented with a single custom
    CUDA split-K tiled GEMM kernel, optimized for the large-K / small-M,N
    regime (M=N=256, K=524288).
    """
    def __init__(self):
        super(ModelNew, self).__init__()

    def forward(self, A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
        if not A.is_cuda:
            A = A.cuda()
        if not B.is_cuda:
            B = B.cuda()
        return _ext.matmul_forward(A, B)

